    sh_state.mode = SH_FAULT;
    sh_state.dropouts = 0;
}

// 2. Fault Latch Persistence
if (sh_state.mode == SH_FAULT) {
    sh_output.mode = SH_FAULT;
    sh_output.q_bi = sh_state.last_q_bi;
    sh_output.relative_step_rad = 0.0;
    return;
}

// 3. Disabled State Handling
if (!sh_input.enable) {
    sh_output.mode = SH_OFF;
    sh_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    sh_output.relative_step_rad = 0.0;
    sh_state.dropouts = 0;
    sh_state.last_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    sh_state.mode = SH_OFF;
    return;
}

// 4. Sample Validation
int valid_sample = (sh_input.valid == 1) && (sh_input.q_bi != NULL);
adcs_quat_t norm_q = {0};
int norm_ok = 0;

if (valid_sample) {
    if (adcs_quat_normalize(sh_input.q_bi, &norm_q) == ADCS_OK) {
        norm_ok = 1;
    }
}

if (!norm_ok) {
    // Rejection
    sh_state.dropouts++;
    if (sh_state.dropouts > sh_config.max_hold_cycles) {
        sh_state.mode = SH_FAULT;
        sh_output.mode = SH_FAULT;
        sh_output.q_bi = sh_state.last_q_bi;
        sh_output.relative_step_rad = 0.0;
    } else {
        sh_state.mode = SH_HOLD;
        sh_output.mode = SH_HOLD;
        adcs_quat_t pub_q = sh_state.last_q_bi;
        double w_err = fabs(pub_q.w - 1.0);
        double v_err = sqrt(pub_q.x * pub_q.x + pub_q.y * pub_q.y + pub_q.z * pub_q.z);
        if (w_err < 1.0e-6 && v_err < 1.0e-6) {
            pub_q = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        }
        sh_output.q_bi = pub_q;
        sh_output.relative_step_rad = 0.0;
    }
    return;
}

// 5. Accepted Sample Processing
adcs_quat_t old_last_q = sh_state.last_q_bi;
double dot_pos = adcs_quat_abs_dot(&norm_q, &old_last_q);
adcs_quat_t neg_q = { -norm_q.w, -norm_q.x, -norm_q.y, -norm_q.z };
double dot_neg = adcs_quat_abs_dot(&neg_q, &old_last_q);

adcs_quat_t final_q = (dot_neg > dot_pos) ? neg_q : norm_q;

sh_state.last_q_bi = final_q;
sh_state.dropouts = 0;
sh_state.mode = SH_TRACK;

double abs_dot = adcs_quat_abs_dot(&final_q, &old_last_q);
if (abs_dot > 1.0) abs_dot = 1.0;
double rel_step = 2.0 * acos(abs_dot);

sh_output.mode = SH_TRACK;
sh_output.q_bi = final_q;
sh_output.relative_step_rad = rel_step;

